/* Official textbook reconciliation: supplied pages 30–61, paraphrased. */
const textbookRecords=[{"page": 30, "session": 1, "unit": "cycle", "title": "葡萄藤的四部分结构与一年生木", "paragraphs": ["世界各地的葡萄品种很多，但葡萄藤的基本结构相似。第4章从这些共同点出发，解释各组成部分的名称与作用：绿色部分、一年生木、多年生木和根系。", "绿色部分是每年新长出的组织。新枝上有叶子、嫩芽、卷须，以及花朵或果实；下一页图4.1进一步展示新枝的主要结构。", "当年的新枝在冬季成为木质枝条，到次年春季称为一年生木。前一年在枝条上形成的芽萌发成新枝；通常只有从前一年嫩芽长出的新枝才能结果，因此一年生木的管理关系到下一季的结果潜力。不要把它理解为葡萄直接长在光秃的老枝上。", "每年冬季需要修剪。按保留芽数，一年生木可留成长枝或短枝：长枝较长，通常保留8–20个芽；短枝较短，通常保留2–3个芽。课本在p.51起继续讨论修剪，具体管理内容见Session 2“冬剪与夏剪”。", "多年生木是超过一年的木质部分，包括主干及干臂（若有）。修剪方式会限制其数量、塑造其结构，不是每棵葡萄藤都有相同的多年生木形态。整枝方法的进一步讨论见p.51及Session 2“密度与整枝”。"], "rows": [["绿色部分", "每年新生的部分；新枝带叶、芽、卷须、花或果实。"], ["一年生木", "上一季新枝木质化后的枝条；可留成长枝（8–20芽）或短枝（2–3芽）。"], ["多年生木", "超过一年的主干和可能存在的干臂，构成长期保留的结构。"], ["根系", "吸收水与养分、固定葡萄藤，并储存越冬所需碳水化合物。"]]}, {"page": 30, "session": 1, "unit": "roots", "title": "根系的三项功能与嫁接背景", "paragraphs": ["根系不仅从土壤中吸收水分与养分，还把葡萄藤固定在土中，并储存葡萄藤越冬所需的碳水化合物。记忆时要同时保留“吸收、固定、储存”三项功能。", "现代葡萄园中的大多数欧亚葡萄不抗根瘤蚜。根瘤蚜是一种侵袭葡萄藤根系的害虫，因此常将欧亚葡萄嫁接在其他葡萄种类的根系上，以保留所需品种的地上部分并利用砧木的抗性。课本p.34继续解释根瘤蚜与砧木，本单元后文已有对应内容。"], "rows": []}, {"page": 31, "session": 1, "unit": "cycle", "title": "看懂绿色部分与木龄", "paragraphs": ["新梢上的叶片负责光合作用：利用光能，把水与二氧化碳转化为葡萄糖，并释放氧气。糖供生长与成熟使用，不是从土壤里直接吸上来的。", "卷须用于攀附：葡萄藤不能独立保持直立，新梢借卷须缠住铁丝等支撑物。花聚集成花序；花含雄性与雌性部分，成功受精的花可发育为一颗浆果，一束花序因而可能变成果串。甜果实吸引动物，有利于种子的传播。", "芽长在叶片与新梢相接的位置。未立即萌发的芽可在当年形成下一年新梢、叶片、花与卷须的微小结构。不要把“下一年才萌发”误解为冬天才开始形成。", "图4.1—4.3区分三种组织：当年绿色新梢；上一季新梢木质化形成的一年生木（可留成短枝或长枝）；保留多年的主干、干臂等永久结构。西班牙的短枝修剪照片和阿尔萨斯的替换长枝照片，重点是辨认木龄与保留结构。"], "rows": []}, {"page": 32, "session": 1, "unit": "roots", "title": "欧亚种与美洲种的用途", "paragraphs": ["欧亚葡萄 Vitis vinifera 包含绝大多数常见酿酒品种。北美原生葡萄通常不因其果实风味而被选作主流酿酒原料；它们抗根瘤蚜的能力，使其在砧木育种中非常重要。这里的“种”与霞多丽这样的“品种”不是同一层级。", "图4.4的澳大利亚葡萄藤展示：水平多年生干臂连接主干，一年生短枝留在其上。看到水平枝条时，必须先判明它是永久主蔓，还是今年保留、之后替换的一年生长枝。"], "rows": []}, {"page": 32, "session": 1, "unit": "propagation", "title": "保留品种：扦插与压条", "paragraphs": ["消费者关注颜色、风味和品质，种植者还必须考虑萌芽时间、成熟速度与抗病性。同一品种可以用 cultivar 等术语指称；不能把教材译文中的“品种”一概理解成生物学的 species。", "要保留一个品种的性状，不能用种子繁殖来代替无性繁殖。扦插把一段枝条培育成新植株，商业苗圃常用；压条在葡萄园中把仍连接母株的长枝弯下，将中段埋土、枝梢露在地上，埋入的部分生根，数年后切断与母株的连接。", "两者都能延续母株性状。压条长出的根仍来自原植株，不能获得嫁接抗性砧木带来的根瘤蚜保护，因此课本说现代栽培多选择扦插培育并配合嫁接。一个克隆群可由同一母株经连续扦插和／或压条繁殖而来。"], "rows": []}, {"page": 33, "session": 1, "unit": "propagation", "title": "克隆选择与新品种培育", "paragraphs": ["无性繁殖保持品种身份，但生长中仍可能出现突变。若突变带来更好的果实品质、抗病性等特点，可以继续无性繁殖来保留，这就是克隆选择。克隆之间通常差别较小；订苗时可以同时指定品种与克隆。", "少数突变影响很大，习惯上被当作不同品种：课本举 Pinot Blanc、Pinot Gris、Pinot Noir 与 Meunier，它们与古老 Pinot 的变异有关。不能把这种变异当作不同亲本授粉杂交的同义词。", "育种希望改善气候和土壤适应性、抗病性、质量或产量。人工异花授粉把一个亲本的花粉用于另一个亲本，受精后形成含种子的果实。播下这些种子，后代的基因组合不同于亲本；即使亲本同属一个品种，也不能保证后代复制原品种。", "传统选育需等待至少两年观察开花结果和果实表现，遗传标记可帮助更早筛选。培育成功也不等于商业成功：消费者对陌生品种的接受度限制了新品种的推广。"], "rows": [["同种亲本 → 种内杂交 crossing", "不只欧亚葡萄才有种内杂交；日常教学常用此词指研究者培育的品种。"], ["Cabernet Sauvignon", "Cabernet Franc × Sauvignon Blanc；现代遗传分析确认亲本关系。"], ["Müller-Thurgau", "Riesling × Madeleine Royale，不能按名字误认成其他亲本。"], ["Pinotage", "Pinot Noir × Cinsault。"]]}, {"page": 34, "session": 1, "unit": "roots", "title": "根瘤蚜为什么难处理", "paragraphs": ["根瘤蚜原产北美，19世纪传入欧洲后造成严重破坏。生命周期复杂，部分阶段在地下取食根系；伤口可被病原体进一步侵染，植株在数年中衰弱甚至死亡。", "共同演化的美洲葡萄具有防御机制：分泌黏液影响害虫取食，并在伤口形成保护层，减少继发感染。欧亚葡萄一般缺乏相同保护。课本列出智利、阿根廷部分地区、南澳大利亚等例外背景，并强调严格检疫；这些是本版课本例子，不等于任何地点永久无风险。", "课本不把化学药剂当成解决根瘤蚜的可靠办法。抗性砧木嫁接使地上部分保留欧亚品种，同时获得根系抗性；苗木成本会增加。砧木还可用于线虫防御、改善耐旱性，因此没有根瘤蚜的地方也可能选择嫁接。"], "rows": []}, {"page": 34, "session": 1, "unit": "propagation", "title": "种间杂交与用途", "paragraphs": ["Hybrid 指不同葡萄种的亲本形成的后代，典型组合中至少有一个美洲葡萄亲本。不能把嫁接叫作 hybrid。课本用加拿大的 Vidal 说明：虽然许多这类葡萄主要用于砧木，仍存在以果实酿酒的例外；美洲种的种内杂交与种间杂交都可用于砧木培育。"], "rows": []}, {"page": 35, "session": 1, "unit": "roots", "title": "嫁接的过程、时间与成本基准", "paragraphs": ["室内嫁接 bench grafting：苗圃可用机器连接接穗与砧木，在温暖条件下使接口愈合，再培育、栽种。图4.5要认出接穗上的芽，以及覆盖接口、起保护作用的红蜡。", "头接枝法 head grafting：把现有葡萄藤剪到保留主干，将所需品种的芽或枝段接上。图4.6展示绑带固定和修剪漆保护接口，以及成活后的生长。成功后可在下一年结出新品种果实；新栽葡萄藤通常至少第三年才有商业收成。", "成本必须说明比较对象：相对于拔除整园、重新栽种，换接可利用既有根系，转换品种更快、成本更低；这与课堂强调田间操作需要人工并不矛盾。原课件中“换接成本高”的概括不能当作与重植比较的答案。"], "rows": []}, {"page": 36, "session": 1, "unit": "cycle", "title": "年度循环与成熟起点", "paragraphs": ["冬季休眠时没有绿色部分；春季萌芽、新梢生长；晚春至初夏开花和坐果；随后果粒增大，但在转色前仍绿色、坚硬、低糖高酸。夏末至秋初进入成熟阶段，果实变软、多汁、糖增加、酸下降并发展风味。", "转色 véraison 是成熟开始的重要标志，而不是采收或完全成熟的同义词。红葡萄与白葡萄都会转色，最终颜色随品种不同；秋季采收、落叶后回到休眠。第6章的月份与管理动作另放在 Session 2，并在本单元提供跳转。"], "rows": []}, {"page": 36, "session": 1, "unit": "needs", "title": "五个条件如何一起工作", "paragraphs": ["热量决定葡萄藤能否正常生长；阳光提供光合作用能量；水和二氧化碳是光合作用的原料；土壤养分支持植株功能。生成的糖供生长、果实成熟与储存使用，氧气经叶片释放。", "本章把二氧化碳视为通常供应充足的条件；更需要比较的变化是温度、日照、水分与养分。这些条件共同影响每个生长阶段，最终影响果实数量与质量。"], "rows": []}, {"page": 37, "session": 1, "unit": "needs", "title": "热量需求、纬度与五种来源", "paragraphs": ["课本以约10°C作为开始生长的温度提示；萌芽、开花、坐果、成熟还各需足够热量。不同品种需求不同：雷司令可在凉爽地区成熟，不代表歌海娜也能在同样条件下成熟。", "大多数葡萄园位于南北纬30°—50°，与热量及休眠需求有关，但海拔等因素使范围外也存在适种地区。赤道附近太阳能量集中在较小面积；高纬度入射较斜，同样能量分布在更大面积。这是图5.2的机制。", "图5.1的来源要逐项记：热量来自太阳及地表再辐射；光来自太阳与水面反射；二氧化碳来自大气；水来自降雨、灌溉与土壤储水；养分来自土壤颗粒、腐殖质和肥料。光与热不能互相替换作答。"], "rows": []}, {"page": 38, "session": 1, "unit": "climate", "title": "海拔、洋流与雾的具体例子", "paragraphs": ["海拔升高通常降温，阿根廷北部 Cafayate 是接近低纬度仍可借高海拔栽培的课本例子。", "洋流输送冷或暖的海水，调节沿岸气候：Humboldt 洪堡／洪德寒流影响智利，Benguela 本格拉寒流影响南非；Gulf Stream 墨西哥湾流为欧洲西北部提供增温影响。", "雾可让过热的葡萄园降温，课本举加利福尼亚及智利 Casablanca Valley。雾同时会减少光照，所以不能只写“雾越多越有利”。"], "rows": []}, {"page": 38, "session": 1, "unit": "soil", "title": "土壤也影响热量", "paragraphs": ["深色表土、石块及岩石可吸收并再辐射热量，在凉爽地区有助成熟；湿土需要更多能量升温，可能推迟萌芽。图5.3以西班牙 Priorat 展示近处多石地表和远处陡坡梯田，两项特征都要看见。"], "rows": []}, {"page": 39, "session": 1, "unit": "climate", "title": "朝向、大陆度、昼夜温差", "paragraphs": ["朝向是坡面面对的方向。朝赤道的坡面通常获热更多：北半球偏南、南半球偏北。高纬度凉爽地区尤其依赖合适朝向与坡度；Mosel 的有利陡坡是教材例子。", "大陆度比较最热月与最冷月的温差，影响生长季长短、总热量和适用品种。海洋、湖泊升温降温比陆地慢，夏季降温、冬季缓和寒冷，通常降低大陆度；内陆更易出现季节极端。", "昼夜温差比较白天与夜间。凉夜有助保留酸与香气，暖夜会加快成熟中的变化。大水体甚至河流可夜间保温、白天带来凉风，缩小昼夜温差。云层也会缩小温差：白天遮阳，夜里减少散热；晴朗无云的夜晚降温更快。"], "rows": []}, {"page": 39, "session": 1, "unit": "needs", "title": "冬季过冷与过暖都有风险", "paragraphs": ["教材提示低于约−20°C可能严重伤害甚至杀死葡萄藤，嫁接部位尤其脆弱；可培土保护。阈值随品种与条件不同，不是所有植株统一的死亡温度。", "冬季过暖或缺少真正冬季时，休眠可能不足，甚至出现一年两季生长结果，影响寿命和品质；暖冬还可能让更多害虫越冬。不能把“冬天越暖越好”当结论。"], "rows": []}, {"page": 40, "session": 1, "unit": "needs", "title": "春霜的四种保护方式", "paragraphs": ["春季近地面的低于0°C空气与结冰会损伤嫩芽、新梢，造成减产。保护要结合低温类型、时机和现场条件。"], "rows": [["加热器", "在园内分布并于霜冻预警时运行，增加热量并促进空气流动；图5.4是 Napa County 的实例。"], ["风机", "利用较暖上层空气与近地冷空气混合；有的带加热装置，不能在缺少暖空气层时期待相同效果。"], ["洒水器", "水结冰时释放潜热，保护组织；依赖连续合适供水与正确操作，不是随意洒一点水。"], ["葡萄园设计", "冷空气下沉，避开低洼积冷处；坡中部及畅通排冷路线能降低风险，较高的葡萄藤结构也可远离最冷近地层。"]]}, {"page": 41, "session": 1, "unit": "needs", "title": "生长季温度与光照风险", "paragraphs": ["寒春可能延迟萌芽、缩短成熟窗口；开花坐果期间低温会降低产量。长期极端高温即使供水充足，也可能使植株活动放缓甚至停止，阻碍成熟，严重时致死。", "酷热干燥增加野火风险。教材举加利福尼亚、智利、澳大利亚的受灾背景；火可毁园和建筑，烟雾影响范围更广。成熟果实受烟可能使酒带烟雾或塑料样异味，后续处理难以完全消除。", "阳光不足会降低光合作用与糖积累，开花坐果也受影响；需要的是足够有效光照，而非全天持续强光。图5.5把地形与气候连起来：封闭洼地积冷、开放坡面排冷；迎向赤道的合适坡面获光获热；高海拔降温；海风和雾可把寒流的凉意带入内陆，暖流则可相反。"], "rows": []}, {"page": 42, "session": 1, "unit": "needs", "title": "光照因素与灌溉比较", "paragraphs": ["高纬度夏季白昼较长，额外日照帮助德国雷司令成熟。临近海洋、湖泊常多云，内陆往往更晴朗；位于河湖上方的园地有时可受益于水面反射。朝赤道的有利坡面能弥补高纬度较弱光照。", "开花坐果遇多云会减产，成熟期厚云会限制糖积累。强烈直射也可能晒伤果皮、带来苦味；应通过冠层管理，在少光处提高受光，在强光处保留适度遮阴。", "根吸收的水送到叶片，叶片通过蒸腾散失水分。气温越高，补水需求通常越大。形成足够叶片之后，适度限制水分可抑制新梢过旺、减少遮阴并促进成熟；前提是仍有足够水维持光合作用，不能与严重干旱混淆。降雨不足时还须考虑法律与可用水源。"], "rows": [["滴灌", "每株附近的滴头可精确供水，能够配合电脑控制；图5.6为新西兰系统。"], ["喷灌", "耗水较多，也使环境潮湿而增加病害风险；合理设计的系统还可防霜。"], ["漫灌", "成本较低，但需要平坦或非常缓坡的地形，以及大量且接近的水源。"]]}, {"page": 43, "session": 1, "unit": "needs", "title": "缺水、积水、降雨时点和冰雹", "paragraphs": ["短暂缺水时植株可减少蒸腾；长期严重缺水会使光合作用停止、叶片萎蔫、果实不能成熟，最终受损甚至死亡。", "水过多会继续推动枝叶生长、争用糖并形成遮阴；积水使根区缺氧，极端时根死亡。坡地和排水管可帮助排除多余水分。", "降雨时点与总量同样重要：开花坐果暴雨会减产；潮湿利于病害；临收获暴雨使果粒膨大、风味稀释，严重时裂果并继发腐烂。", "冰雹可伤果、伤藤甚至毁掉收成。Mendoza 是课本例子；防雹网成本高，但高风险地点可能值得投入。因冰雹常局部发生，把园地分散在不同地点能分散风险，不能保证完全无损。图5.7展示的是防雹设施，不要与图6.6的防鸟网用途混淆。"], "rows": []}, {"page": 44, "session": 1, "unit": "climate", "title": "气候、天气与温度分类口径", "paragraphs": ["气候描述多年温度、日照、降雨的平均模式；天气描述具体时期相对这种模式的变化。气候可在几十年尺度改变，课本也讨论升温、干旱洪水等极端事件，以及行业的适应和减缓。", "波尔多2013年寒冷潮湿、2015年大部分时间温暖干燥，是本版教材用于解释年份差异的例子；加州 Central Valley 的炎热干燥天气相对稳定。不是把单一年份当作永久气候标签。", "本书的生长季平均温度计算口径：北半球4—10月，南半球10月至次年4月。凉爽类别为16.5°C或更低，修正讲义简表中“低于16.5°C”的边界遗漏。"], "rows": []}, {"page": 45, "session": 1, "unit": "climate", "title": "四档温度与三类气候", "paragraphs": ["温和为16.5—18.5°C，温暖为18.5—21°C，炎热高于21°C；课本区间使用连续端点简写，不能把端点误差变成独立知识点。分类还要包括大陆度、昼夜温差、降雨时间与总量、阳光强度及日长。"], "rows": [["大陆性", "季节温差大，常夏季较短、入秋降温快。Chablis、Champagne 是凉爽大陆性例子：有春霜与成熟不足风险，适宜较晚萌芽、较早成熟的品种。夏季常干，温度高时可能需灌溉。"], ["海洋性", "通常凉爽或温和、大陆度低，雨量全年较均匀；温和秋季可延长成熟，但春夏降雨干扰开花坐果，采收季降雨危及果实健康。"], ["地中海", "大陆度较低、夏季温暖干燥；课本举地中海沿岸、加州大部分沿海及智利、南非、澳大利亚适用地区。相较海洋性，常见较饱满酒体、成熟单宁、较高酒精及较低酸，但仍取决于品种和地点。少雨利于健康，也有干旱风险。"]]}, {"page": 45, "session": 1, "unit": "soil", "title": "土壤由什么构成", "paragraphs": ["土壤位于岩床之上，厚度可从数厘米到数米，由不同大小的矿物颗粒、较大石块与腐殖质等组成。颗粒可来自基岩风化或沉积物，粒径与比例比单说来源更有解释力。", "石块最大，但并非每个园地都有；细颗粒中砂比黏土大。地表石块参与储热。腐殖质来自动植物残体分解，能提供养分并保持水分。", "水分管理有阶段性：早期需要足够水长成叶幕，转色后适度限制可帮助成熟；这不是鼓励持续严重缺水。"], "rows": []}, {"page": 46, "session": 1, "unit": "soil", "title": "保水、排水与养分闭环", "paragraphs": ["水可与黏土颗粒、腐殖质结合而留在土中。黏土太多可能排水不良；砂石排水好但保水弱，比例过高时即使多雨地点也可能需要灌溉。砂与黏土适当混合的壤土可兼顾排水与保水，但没有在所有温度和降雨条件下都最好的土壤。", "关键养分包括氮、磷、钾，由根吸收。葡萄藤不需极高肥力；过多养分使枝叶旺盛、果实遮阴。随着养分耗用，可能需要天然或化学肥料补充。", "教材图5.8展示法国 Mâconnais 的黄化葡萄藤：缺素相关黄叶会降低光合作用，使成熟、品质和产量受影响，可针对原因施用合适肥料。学习时识别黄叶与绿叶的差别，但不能只看照片就诊断每一种黄化原因。土壤对酒质影响复杂，不能推导出某种石头直接赋予对应味道。"], "rows": []}, {"page": 47, "session": 2, "unit": "training", "title": "建园之前：环境、商业和品种", "paragraphs": ["管理目标是收获健康、成熟并符合酿酒风格的葡萄。选址先评估平均温度、降雨、日照、土壤肥力及排水，它们共同影响品种、密度、整枝和搭架。", "还要评估电力和水源等基础设施距离、可用劳动力、拖拉机与采收机的可获得性、土地成本。品种必须既适合气候又有市场；教材提醒部分产区有法定品种限制，此处不把书中概述当作具体地区最新法规。", "栽种前清理原植被、检测土壤，按需要补充不足养分。嫁接苗可人工或机械种植，保护套管减少动物伤害。教材指出部分限制灌溉地区可对建园幼苗有例外，不能概括为全面禁灌。通常栽种第三年开始有收成。", "多数葡萄藤在30—50年左右被更新，尽管寿命可更长。老藤可能提供浓郁果实，但随龄增加常产量下降、病害增多；“老藤”称呼本身不保证品质，需平衡质量、产量和利润。"], "rows": []}, {"page": 48, "session": 2, "unit": "training", "title": "重植安排与新园设施", "paragraphs": ["按本版教材的一般情境，拔除后土地可休耕3年或更长以恢复；种植者分批安排更新，尽量减少同一时期没有产出的面积。这是课本所述做法，不是所有地区强制统一年限。", "图6.1的新建澳大利亚园地同时有支柱、铁丝、滴灌管和保护幼苗的塑料套管。辨图时不要只看到“搭架”，要说明支撑、供水、防动物伤害这三个不同目的。"], "rows": []}, {"page": 49, "session": 2, "unit": "pruning", "title": "年周期：萌芽与冬季储备", "paragraphs": ["萌芽示例月份：北半球3—4月、南半球9—10月。芽膨大绽开成为新梢，日均温超过约10°C是常用提示；品种不同，所需条件也不同。Chardonnay、Pinot Noir 较早萌芽，Cabernet Sauvignon 较晚，因此春霜暴露风险不同。", "若采用药剂防护体系，萌芽阶段就需开始关注真菌病与虫害防护。图6.2把冬剪后植株、芽膨大展开、新梢、花序、开花特写、坐果、绿色幼果、转色、成熟、采摘、冬剪前植株连成年度循环；具体管理动作见下表。"], "rows": []}, {"page": 50, "session": 2, "unit": "pruning", "title": "把每个阶段与管理动作对应", "paragraphs": ["以下月份是教材的典型季节安排，不替代具体产区与年份判断。喷药仅在需要、许可且符合安全间隔时进行，不把每个阶段写成必须固定喷药。"], "rows": [["生枝长叶｜北3—5月／南9—11月", "开花前新梢生长快；最初利用越冬储存的碳水化合物，叶片成熟后转由光合作用供能。早期需充足水和养分；搭架园绑缚新梢以免风损。"], ["开花坐果｜北5—6月／南11—12月", "温暖、充足光、少雨或无雨有利受精坐果。不是每朵花都形成果实。落花 coulure 是坐果失败高于正常；小粒果／部分僵化 millerandage 可出现小且无籽果粒。寒冷阴雨常加重两者并减产。"], ["转色成熟｜北7—9月／南1—3月", "坐果后约6—8周幼果仍绿且硬；转色开始后红葡萄渐红紫，白葡萄渐透明、金黄。果粒增大、多汁、糖增酸降，风味与单宁等变化。"], ["夏季操作", "必要时修整枝叶以通风透光；轻度水分限制抑制徒长。转色后可摘青调节负载，但不是所有生产者都采用。"], ["采收｜北9—10月／南3—4月", "干燥天气更理想；临收雨可稀释和增加腐烂。接近采收需按规定提前停止相关药剂，避免有害残留。"]]}, {"page": 51, "session": 2, "unit": "pruning", "title": "休眠、整枝与冬剪的关系", "paragraphs": ["冬季休眠示例：北半球12月至次年3月、南半球6—9月。新梢逐渐木质化成为长枝，根部储存碳水化合物供下一季使用；极冷可伤芽、杀藤，培土可提供保护，随后进行冬剪。", "管理综合温度、光、水、养分及机械条件，目标是在达到品质要求的同时，以合理成本获得适合的产量，而不是一律追求最低产。冬剪确定芽的数量与位置；芽不要挤在一起，便于后续冠层管理。"], "rows": []}, {"page": 51, "session": 2, "unit": "training", "title": "头状与主蔓：永久结构不同", "paragraphs": ["头状整枝多年生木较少，可只有主干，也可在顶端有几根短干臂；能配合短枝或替换长枝修剪。", "主蔓整枝保留一根主干及一根或多根水平多年生主蔓，通常配合短枝修剪。建立较多永久木需要更长时间，但稳固结构和规则分布有利机械化。常见1—2根主蔓，大树型也可有4根或更多。", "两类整枝都可做低或高：低位可利用地表热量，高位可远离最冷近地空气。不要把“头状”等同“永远矮、不搭架”，或把“主蔓”误认成一年生长枝。"], "rows": []}, {"page": 52, "session": 2, "unit": "pruning", "title": "以课本明确留芽数量", "paragraphs": ["本次收到的课本明确写短枝保留2—3个芽；替换长枝通常8—20个芽，并常保留1—2根长枝水平绑缚。复习本版教材时使用这一口径。课堂转写的“1—2芽”保留为来源差异，不再标作教材尚待确认。", "替换长枝修剪较复杂，需要熟练人员选择合适枝条；单居由式 single guyot 保留一根，双居由式 double guyot 保留两根。主干上绑的长枝是可替换的一年生木，不是永久主蔓。", "夏剪控制枝叶生长与遮阴，使糖更有效用于果实；可去除部分叶片增加果串受光，但炎热强光处须保留必要遮阴，不能把“摘叶越多越好”当规则。"], "rows": []}, {"page": 52, "session": 2, "unit": "canopy", "title": "搭架的三个理由与两种 VSP", "paragraphs": ["冠层包含所有绿色部分；搭架由支柱和铁丝支撑长枝与新梢。目的有三：调节光照以适合当地；改善空气流动与干燥、减少病害；便利机械采收与更有效的喷洒。", "灌木形常头状整枝加短枝修剪，新梢自然下垂；适合干燥、光强的温暖或炎热地点，例如 Southern Rhône、Barossa Valley。阴凉潮湿地点过度遮阴与不通风会不利成熟、增病。Beaujolais 会把部分这类新梢顶端绑在一起，改善果串受光通风。未搭架灌木形通常不适合机器采收。", "VSP 将新梢垂直排列并固定，形成狭窄、留有空隙的冠层，可配合短枝或长枝修剪。在炎热光强处，可用调整型 VSP：不绑住顶梢，允许其下垂以遮阴，同时保留机械采收的可能。"], "rows": []}, {"page": 53, "session": 2, "unit": "pruning", "title": "图6.3：冬剪之后与转色之后", "paragraphs": ["三种结构必须分开认：①头状整枝＋短枝修剪，不搭架的新梢自然展开；②头状整枝＋替换长枝，一年生长枝水平绑在铁丝上，新梢可做VSP；③主蔓整枝＋短枝修剪，短枝长在多年生主蔓上，新梢也可做VSP。", "原图每株左侧画冬剪后的木质结构、右侧画转色后的冠层。不要理解成葡萄藤实际只有一边长叶；也不要把右侧绿色当年新梢与左侧褐色一年生木混为一谈。下方插画把三个冬季结构单独列出，夏季VSP另示。"], "rows": []}, {"page": 54, "session": 2, "unit": "training", "title": "密度与芽数必须一起考虑", "paragraphs": ["种植密度按每公顷株数表示，教材范围示例为1000—10000株／公顷；1公顷是100×100米，1英亩约0.4公顷。密度不是单株负载，也不是产量。"], "rows": [["水源非常有限", "低密度减少根系抢水，让每株利用更大土壤范围。"], ["肥力低而雨水足", "水足也可能导致旺盛枝叶；高密度引入竞争，但要与冬剪留芽数配合。芽太少，每芽分得储备过多，容易徒长；芽太多则资源不足，成熟受阻。欧洲不少园地采用高密度并控制单株芽数。"], ["肥力高且雨水足", "高密度可能仍压不住旺长；可用低密度、大植株、多主蔓／长枝分配生长势，兼顾高产与质量。"]]}, {"page": 54, "session": 2, "unit": "balance", "title": "产量的单位、预测与摘青风险", "paragraphs": ["产量可按葡萄重量表示（吨／公顷），也可按酒的体积表示（百升／公顷）。生产者要满足产区限制、合同与酒厂接收和容器容量安排，因此必须预测，但冬剪留芽数只是起点：霜冻、坐果率、病虫害都会改变结果。", "若预计产量过高，可在转色后摘除部分未熟果串。时机不当会触发剩余果粒增大，抵消数量下降，甚至稀释风味。低产与高品质不是必然因果，资源、冠层、成熟与目标风格需一起判断。"], "rows": []}, {"page": 55, "session": 2, "unit": "balance", "title": "课本实例一：炎热、干燥、缺少灌溉", "paragraphs": ["条件全部保留：内陆、炎热、强光、少雨；没有或只有极有限灌溉水，但土壤保水良好。例题暂不考虑法规限制。", "水最紧缺，所以选择低密度，让每株有足够根区取水、减少竞争。强光和热带来晒伤风险，因此可选灌木形，或让搭架植株顶梢下垂遮阴。少雨使潮湿真菌病风险相对低，遮阴的取舍更合理。", "图6.4展示西班牙低密度灌木形园地；要看株间较大间隔、低矮独立植株和缺少连续铁丝架，而不只是说“干旱”。"], "rows": []}, {"page": 56, "session": 2, "unit": "balance", "title": "课本实例二：温和、海边、多雨、贫瘠", "paragraphs": ["条件全部保留：接近海洋、温和、全年雨多、土壤贫瘠；同样暂不考虑法规。不要漏掉“雨水充足”，以为贫瘠就一定长势弱。", "采用高密度增加植株竞争以约束生长；多雨带来真菌病风险，多云又限制光照，因此用开放、通风的VSP冠层，增加受光、促进干燥。", "图6.5的波尔多照片还展示头状整枝、替换长枝修剪与高密度的组合。上述两个实例体现条件→选择→影响，不能变成所有海边或内陆园地的固定配方。"], "rows": []}, {"page": 57, "session": 2, "unit": "health", "title": "根、叶和果实的受害路径", "paragraphs": ["果实被吃或受感染会减产、降质；叶片损伤降低光合作用，继而阻碍成熟；某些病虫害还可杀死植株。根瘤蚜的完整机制回看 Session 1 的砧木单元。", "线虫是很小的蠕虫，侵袭根系、妨碍水和养分吸收，部分还能传播病毒。教材强调预防优于事后治疗，举重植前土壤处理和抗性砧木；具体处理须针对实际问题。", "鸟和哺乳动物不仅吃掉果实，咬伤处也增加真菌感染风险。防鸟用网；兔、鹿、野猪等可用围栏。图6.6是新西兰覆盖果区的防鸟网。昆虫可取食叶与果，控制可采用相应杀虫剂，或综合虫害管理等方案。"], "rows": []}, {"page": 58, "session": 2, "unit": "health", "title": "三类霉菌问题：表现、后果与控制", "paragraphs": [], "rows": [["霜霉病 downy mildew", "教材归在真菌病害教学组。温暖潮湿有利发生，侵袭绿色部分；叶片黄斑、叶背灰白绒状生长，严重时早落叶；花序、幼果也受害并减产。"], ["白粉病 powdery mildew", "温暖、阴暗、有一定湿度时有利；绿色部分出现灰白粉层，叶片可干枯早落，果粒可萎缩、开裂或成熟异常。"], ["灰腐 Botrytis cinerea", "潮湿利于感染果实，损坏风味并使红葡萄酒颜色变浅。某些白葡萄在适当条件下可形成有益贵腐；具体酿甜酒章节p.85本次未提供。"], ["传统防治例子", "硫制剂用于白粉病，含铜的波尔多液用于霜霉病。也有其他药剂；多雨环境常需更频繁防护，接近采收需遵守停药与安全间隔。"], ["冠层管理", "密闭叶幕滞留湿气；开放冠层促进流通蒸发、减少病害，可减少用药和成本，需喷洒时也更易覆盖目标。"]]}, {"page": 58, "session": 2, "unit": "health", "title": "病毒、细菌与常规投入", "paragraphs": ["病毒常不会立即杀死植株，但可限制正常功能，降低产量与品质；可通过受感染的繁殖材料或线虫等传播，具有持续性。教材强调没有直接治愈手段、需要清除受感染植株并进行相应地块处理。", "细菌病害可减产降质，严重者致死；教材举叶蝉等媒介传播，强调检疫、打断媒介生命周期与移除感染植株。教材将移除及土壤处理作概括，不能把它当成所有病原都可用同一种消毒方式根除的技术保证。", "20世纪后半叶，定期系统使用农药与化肥增加；环境影响推动生产者、消费者与立法者减少依赖。以下可持续、有机、生物动力是课本列出的三种替代取向，常规栽培作为比较背景保留。"], "rows": []}, {"page": 59, "session": 2, "unit": "health", "title": "三种栽培取向的细节", "paragraphs": [], "rows": [["可持续栽培", "不等于完全禁用化学品，而是根据害虫生命周期、天气与监测选择有效时机，减少例行喷药。综合虫害管理可引入天敌；多样植物提供栖息地、吸收二氧化碳，翻入土中可补充养分。"], ["有机栽培", "与可持续有重叠，但允许投入的种类与剂量受认证标准限制。标示认证需相应机构认可；机构标准可不同，并有按有机方式经营一段时间的转换要求，不能把某个固定年限套给所有认证。"], ["生物动力栽培", "课本提到 Rudolf Steiner 与 Maria Thun；以有机做法为基础，加上把土壤、地球、大气及天体视为关联整体的理念，按天体周期安排操作，并使用特定“制剂”；也有认证机构。这些理念的存在不等于它们所有因果主张均已获科学证实。"]]}, {"page": 59, "session": 2, "unit": "harvest", "title": "成熟标准与酒厂接收能力", "paragraphs": ["从转色开始，糖增加、酸下降，风味发展，单宁通常变得不那么苦涩。监测糖分是常见成熟追踪方法，但不能代替酸、风味、单宁和健康状况的综合判断。", "理想平衡随品种、气候和目标酒风格／品质而变化，没有一个适用于所有酒的绝对成熟数值。种植者与酿酒师共同决定采收；恶劣天气预报可能迫使提前，以避免冰雹损伤或降雨膨果稀释。", "还需协调采摘、运输与酒厂处理的时间，避免短时间送到太多葡萄而无法及时加工。"], "rows": []}, {"page": 60, "session": 2, "unit": "harvest", "title": "机器采收：速度、温度和完整性", "paragraphs": ["选择采收方式取决于整枝与搭架、地形、劳动力、成本、天气和酿造需求；两种方式都可能生产优质酒。机器跨过葡萄行，通过振动使果粒脱落、接住收集，果梗通常留在藤上，再输送至拖车；图6.7是法国实例。", "传统机器采收选择性有限，可能混入不健康、未熟、破损果粒，以及叶片、昆虫等 MOG（matter other than grapes，非葡萄果实物质）。酒厂分选可移除杂物，部分机器也有分选功能；不能把所有现代机器一概写成没有任何选择。", "速度快可赶在坏天气前完成，或在品种迅速过熟前采收，课本举长相思。夜间采低温果实，可降低之后冷却成本与能耗，减慢氧化并减少过早发酵风险。", "适合平地或缓坡、可通行的行距与树形，以及容易脱梗且不易受损的果实。不能提供酿造所需完整果串；课本用需整串的 Beaujolais、Champagne 情境说明，不能扩展为这些地区所有酒款的绝对规则。"], "rows": []}, {"page": 61, "session": 2, "unit": "harvest", "title": "人工采收：挑选、整串与陡坡", "paragraphs": ["工人用剪刀剪下整串，速度较慢且劳动需求大，劳动力有限时成本尤其高。可在园内挑选，留下未熟或腐烂果；贵腐发展程度在串与串、甚至同串果粒间不同，需要仔细选择，可能分多次进行。", "人工采收通常较少损伤果实，小而浅、可叠放的容器可进一步减压。保留果梗的完整果串有利于整串压榨得到清洁果汁，或用于需要整串发酵的红葡萄酒。", "陡坡难以使用常规采收机，课本举 Douro、Mosel、Northern Rhône 的陡坡园地；图6.8是阿根廷人工采收。这里说的是陡坡作业情境，不是说这些产区任何平坦地块都只能人工采收。"], "rows": []}];
const textbookFigures=[[1, "4.1", 31, "cycle", "葡萄藤结构", "botany", "1、2：叶片、卷须、花序、腋芽；细的一年生木与粗的多年生木。"], [1, "4.2", 31, "cycle", "西班牙短枝修剪", "management", "1：头状骨架上的短枝；辨认一年生木与主干、干臂。"], [1, "4.3", 31, "cycle", "阿尔萨斯替换长枝", "management", "2：保留一年生长枝，与永久主干区分。"], [1, "4.4", 32, "roots", "澳大利亚主蔓短枝", "management", "3：短枝位于多年生主蔓上。"], [1, "4.5", 35, "roots", "室内嫁接", "botany", "4：接穗、砧木接口与保护蜡；为概念示意，不作为切口操作教程。"], [1, "4.6", 35, "roots", "头接枝法", "botany", "5：利用原有主干和根系换接新品种，固定并保护接口。"], [1, "5.1", 37, "needs", "五个生长条件", "needs", "原有五条件插画配本次补全的来源与氧气释放说明。"], [1, "5.2", 37, "needs", "纬度与能量分布", "latitude", "专门重绘：同量光线在高纬度分布面积更大。"], [1, "5.3", 38, "soil", "Priorat 石块与梯田", "environment", "1：石块再辐射热量、陡坡梯田；插画为组合场景，不冒充产区实景。"], [1, "5.4", 40, "needs", "Napa 防霜加热器", "environment", "2：加热器与风机、洒水器并列说明，各自机制见正文。"], [1, "5.5", 41, "climate", "地形与局部气候", "environment", "1：海风与坡面冷空气流动；正文补全海拔、朝向和洼地积冷。"], [1, "5.6", 43, "needs", "新西兰滴灌", "environment", "3：滴头供水与根区吸收；并非只给单一根点供水。"], [1, "5.7", 44, "needs", "阿根廷防雹网", "environment", "4：上方承接冰雹的保护设施。"], [1, "5.8", 46, "soil", "Mâconnais 黄化", "environment", "5：黄化叶与健康叶的对照，不能凭插画判定全部病因。"], [2, "6.1", 48, "training", "新园设施", "environment", "6：支柱、铁丝、滴灌管与幼苗保护套管。"], [2, "6.2", 49, "pruning", "葡萄园年度循环", "cycle", "已有年周期插画结合新增六阶段作业表，补入萌芽至冬剪的全部图注阶段。"], [2, "6.3", 53, "pruning", "整枝、修剪与冠层", "management", "1—3：三种冬季结构；4：夏季VSP及顶梢下垂的调整型。"], [2, "6.4", 55, "balance", "西班牙低密度灌木形", "cases", "左图：株间距大、独立低矮树形、遮阴；与缺水条件对应。"], [2, "6.5", 56, "balance", "波尔多高密度园地", "cases", "右图：密植、头状替换长枝与开放搭架；与多雨贫瘠条件对应。"], [2, "6.6", 57, "health", "新西兰防鸟网", "management", "5：果区覆网；与防雹网的功能区别见正文。"], [2, "6.7", 60, "harvest", "法国机器采收", "management", "6：跨行机器接住果粒并输送；无法提供完整果串。"], [2, "6.8", 61, "harvest", "阿根廷人工采收", "management", "5：剪取整串、仔细挑选并用浅容器保护。"]];

function textbookPlate(key){
 const paths={botany:'assets/textbook-botany.webp',environment:'assets/textbook-environment.webp',management:'assets/textbook-management.webp',cases:'assets/textbook-cases.webp',needs:'assets/needs-editorial.webp',cycle:'assets/cycle-editorial.webp',latitude:'assets/textbook-latitude.svg'};
 const titles={botany:'植物结构、繁殖与成熟',environment:'环境调节与葡萄园防护',management:'从冬季结构到夏季作业',cases:'两种环境，两套管理选择',needs:'五个生长条件',cycle:'一年中的生长阶段',latitude:'同量太阳能，不同的分布面积'};
 return `<figure class="textbook-plate"><img loading="lazy" src="${paths[key]}" alt="${titles[key]}教学插画，详解见下方图号说明"><figcaption>${titles[key]} · 教学重绘，非原书照片。</figcaption></figure>`;
}
function textbookBlock(session,unit){
 const entries=textbookRecords.filter(r=>r.session===session&&r.unit===unit);
 if(!entries.length)return '';
 const figures=textbookFigures.filter(f=>f[0]===session&&f[3]===unit);
 const gallery=[...new Set(figures.map(f=>f[5]))].map(k=>textbookPlate(k)+`<ul class="textbook-legends">${figures.filter(f=>f[5]===k).map(f=>`<li><strong>对应图 ${f[1]} · ${f[4]}</strong><span>${f[6]}</span></li>`).join('')}</ul>`).join('');
 const links=session===1&&unit==='cycle'?'<p class="book-crosslink">年度管理与典型月份 → <a href="#session2/pruning">Session 2 · 年周期和作业</a></p>':session===2&&unit==='pruning'?'<p class="book-crosslink">木龄与成熟基础 → <a href="#lesson/cycle">Session 1 · 葡萄藤与年周期</a></p>':'';
 return `<div class="textbook-expansion" id="textbook-${session}-${unit}"><div class="eyebrow">TEXTBOOK / SESSION ${session}</div><h2>课本精读 · 本单元补全</h2><p>以本次提供的课本为依据，保留机制、例子与适用条件；课堂内容继续保留在后面。</p><nav class="book-toc" aria-label="课本段落">${entries.map((r,i)=>`<a href="#book-${session}-${unit}-${r.page}" data-book-jump="book-${session}-${unit}-${r.page}">p.${r.page} · ${r.title}</a>`).join('')}</nav>${entries.map(r=>`<section class="book-section" id="book-${session}-${unit}-${r.page}"><p class="source-note">官方课本 p.${r.page} · Session ${session}</p><h3>${r.title}</h3>${r.paragraphs.map(t=>`<p>${t}</p>`).join('')}${r.rows.length?table(['要点','机制、条件与例子'],r.rows):''}</section>`).join('')}${links}<details class="book-gallery" open><summary>图解与原书图号对照 · ${figures.length} 项</summary>${gallery}</details><p class="fine">课本核对范围为已提供的 p.30—61；第4章开头 p.30 已补齐。所有完整原图与文字仍请结合自己的课本阅读。</p></div>`;
}
function enrichTextbook(){
 lessons.forEach(u=>{u.body=textbookBlock(1,u.id)+u.body;u.duration=Number(u.duration)+10});
 s2Units.forEach(u=>{u.body=textbookBlock(2,u.id)+u.body;u.duration+=8});
}
function textbookIndex(session){
 const unitNames={roots:'砧木与嫁接',propagation:'繁殖与品种',cycle:'葡萄藤年周期',needs:'生长条件与风险',climate:'气候与天气',soil:'地形与土壤',training:'密度与整枝',pruning:'冬剪与年周期',canopy:'搭架与冠层',balance:'产量与品质',health:'病虫害与栽培',harvest:'成熟与采收'};const rows=[];for(let page=session===1?30:47;page<=(session===1?46:61);page++){
 const rs=textbookRecords.filter(r=>r.page===page&&r.session===session);
 rows.push([String(page),rs.map(r=>r.title).join('；'),bookPageLinks(page)]);
 }
 return `<details class="textbook-source audit-fold"><summary><strong>课本逐页核对</strong><span>${session===1?'第4—5章 · p.30—46':'第6章 · p.47—61'}</span></summary><div class="audit-body">${table(['课本页','主题','阅读单元'],rows)}<details class="audit-subfold"><summary>配图索引</summary>${table(['原图号／页','主题','对应知识与图示'],textbookFigures.filter(f=>f[0]===session).map(f=>[f[1]+' / '+f[2],f[4],bookFigureLink(f)]))}</details><p class="fine">两课共32页、22个图号已建索引；原始录音待核听。未提供章节不在核对范围。</p></div></details>`;
}
